const { test, expect } = require('@playwright/test');
const flow = require('../utils/flow');
const { LoginPage } = require('../pages/LoginPage');
const { GoldStockAuditPage, AUDIT_BARCODE_FILE } = require('../pages/GoldStockAuditPage');

// Audits ONE pledged loan's articles, using the loan from the Audit barcode generated by `npm run barcode`
// (test-data/last-audit-barcode.json). Override: $env:LOAN_NUMBER="GLNG0126100000002"; status: $env:AUDIT_STATUS="Damaged"
const STATUS = process.env.AUDIT_STATUS || 'Verified';

test('TC_GOLDSTOCKAUDIT_001 - Gold Stock Audit of one loan (Audit barcode loan) as admin', async ({ page }, testInfo) => {
  const audit = new GoldStockAuditPage(page);
  const bc = GoldStockAuditPage.readAuditBarcode();
  const loanNumber = process.env.LOAN_NUMBER || flow.need('loanNumber', 'token');
  if (bc?.loanNumber && bc.loanNumber !== loanNumber) console.log(`Note: last Audit barcode ${bc.barcode} is for ${bc.loanNumber}, not the flow loan – using the flow loan ${loanNumber}`);
  test.skip(!loanNumber, `No Audit barcode hand-off (${AUDIT_BARCODE_FILE}) – run: npm run barcode`);
  const ref = bc?.barcode ? `Audit barcode ${bc.barcode}` : 'manual';
  console.log(`Auditing loan ${loanNumber} (${ref})`);
  testInfo.annotations.push({ type: 'test-data', description: `${loanNumber} – ${ref} – ${STATUS}` });

  await test.step('Login as admin', () => new LoginPage(page).login('CHECKER_BH'));
  let screen;
  await test.step('Open Loans → Gold → Gold Stock Audit / Gold Audit', async () => { screen = await audit.open(); });
  if (screen === 'workflow') console.log('SKIPPED: this build replaced "Gold Stock Audit" with the "Gold Audit" workflow (auditor → custodian → Branch Head → Head Audit) – needs auditor / custodian / Head Audit logins; not automated yet');
  test.skip(screen === 'workflow', 'Gold Stock Audit replaced by the Gold Audit workflow in this build – needs auditor/custodian/Head Audit users');

  await test.step(`Audit Date (today) and Loan ${loanNumber}`, async () => {
    console.log('Audit date:', await audit.auditDate.inputValue());
    await audit.selectLoan(loanNumber);
    const items = await audit.articles();
    console.log('Articles:\n' + items.map((a) => `  #${a.sno} ${a.purity} | G.WT ${a.grossWt} | N.WT ${a.netWt}`).join('\n'));
    expect(items.length).toBeGreaterThan(0);
  });

  await test.step(`Mark every article "${STATUS}" with a comment`, async () => {
    const n = await audit.articleRows().count();
    for (let i = 0; i < n; i++) await audit.auditArticle(i, STATUS, `${STATUS} by automation – ${ref}`);
  });

  await test.step('Investigation Executive + Overall Comments', async () => {
    const execs = (await audit.executive.locator('option').allInnerTexts()).map((t) => t.trim()).filter((t) => t && t !== 'Select');
    console.log('Investigation Executive options:', execs.join(' | '));
    expect(execs.length).toBeGreaterThan(0);
    await audit.executive.selectOption({ label: execs[0] });
    await audit.overall.fill(`Gold stock audit by automation on ${new Date().toISOString().slice(0, 10)} – ${ref} – all articles ${STATUS}`);
  });

  await test.step('Save', async () => {
    await audit.save.click();
    await expect(page.locator('.toast-message, .swal2-html-container').first()).toBeVisible();
    const msgs = (await audit.messages()).join(' ');
    console.log('Messages after save:', msgs);
    expect(msgs).toMatch(/audit done|success|saved/i); // app says "Gold Audit Done"
    expect(msgs).not.toMatch(/error|fail|please/i);
    flow.update('stock-audit', { auditStatus: STATUS, auditedOn: new Date().toISOString().slice(0, 10) });
    if (bc && !process.env.LOAN_NUMBER) GoldStockAuditPage.markAuditBarcode({ auditedOn: new Date().toISOString().slice(0, 10), auditStatus: STATUS });
  });
});
